4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: simplest case and base premiums ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result.results).toEqual([{ premium: 5 }]);
13	  });
14	  it.todo("a plain sword → base premium 100 G + 10 G first insurance + 5 G fee = 115 G");
15	  it.todo("a plain amulet → base premium 60 G + 6 G first insurance + 5 G fee = 71 G");
16	  it.todo("a plain staff → base premium 80 G + 8 G first insurance + 5 G fee = 93 G");
17	  it.todo("a plain potion → base premium 40 G + 4 G first insurance + 5 G fee = 49 G");
18	  it.todo("a single rune → base premium 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
19	  it.todo("a single moonstone → base premium 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
20	
21	  // --- Components: block of 3 alike ---
