27	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
28	
29	  // --- Premium modifiers in isolation ---
30	  it.todo("cursed sword adds a 50 % risk surcharge on its own base premium (+50 G)");
31	  it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge (+30 G)");
32	  it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
33	  it.todo("cursed sword with enchantment 5 gets both surcharges (+50 G and +30 G)");
34	  it.todo("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
35	  it.todo("customer with 1 year with MHPCO receives no loyalty discount");
36	  it.todo("a first insurance carries a 10 % initial assessment surcharge");
37	  it.todo("the second quote in a scenario receives a 15 % follow-up contract discount");
38	  it.todo("a 5 G processing fee is added to every premium");
39	
40	  // --- Modifier scope on multi-item policies ---
41	  it.todo("cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G → 210 G before further modifiers and fee");
42	  it.todo("item-specific modifiers apply per item; policy-wide modifiers apply to the policy base premium; the fee is added last");
43	
44	  // --- Rounding in MHPCO's favour ---
45	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
46	  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
47	
48	  // --- Integration examples ---
49	  it.todo("newcomer with a cursed sword (0 years, no previous contract) → premium 165 G");
50	  it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G");
51	
52	  // --- Claim: standard reimbursement ---
53	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
54	  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");
55	
56	  // --- Claim: special clauses ---
57	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
58	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
59	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
60	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
61	
62	  // --- Claim: deductible per damage event ---
63	  it.todo("dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");
64	
65	  // --- Claim: rounding ---
66	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
67	
68	  // --- Claim: insurance sum and cap ---
69	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
70	  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
71	  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects the premium only)");
72	  it.todo("sword insured (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G, remaining cap 600 G");
