88	  it.todo("CLI writes premium for quote steps and payout + remainingCap for claim steps");
89	  it.todo("CLI exits with a non-zero status code and writes an error to stderr for an unknown item type, writing no results to stdout");
90	  it.todo("CLI exits with a non-zero status code and writes an error to stderr for an invalid claim");
